motion:
tl.fromTo("#levelart", { scale: 1.00 }, { scale: 1.10, duration: 6.6, ease: "none" }, 2.4);
/* the ramp draws itself on: outline first, then the centre line */
tl.fromTo("#rampline", { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 1.9, ease: "power1.inOut" }, 9.2);
tl.fromTo("#rampmid",  { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 1.4, ease: "power1.out" }, 10.6);
/* the plant: two facts the viewer will need later, landed on the words */
tl.fromTo("#plant1", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 16.7);
tl.fromTo("#plant2", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 18.0);
/* the door: a wedge of stairwell light opens, then is let close softly */
tl.fromTo("#wedge", { width: 0 }, { width: 190, duration: 1.5, ease: "power2.out" }, 47.7);
tl.to("#wedge", { width: 0, duration: 2.6, ease: "power1.inOut" }, 50.4);
/* footsteps cross the light pools one at a time */
[56.1, 56.9, 57.7].forEach((t, i) => {
  tl.fromTo(`#pool${i + 1}`, { opacity: 0.13 }, { opacity: 0.46, duration: 0.2, yoyo: true, repeat: 1 }, t);
});
tl.fromTo("#halo", { opacity: 0.3 }, { opacity: 0.85, duration: 3.0, ease: "sine.inOut" }, 59.3);
/* "I know you're on four": the readout resolves to a fact nobody was told */
tl.to("#lvl", { duration: 1.1, scrambleText: { text: "LEVEL 4", chars: "0123456789", speed: 0.8, revealDelay: 0.35 } }, 59.5);
/* the recall lands as a stamp */
tl.fromTo("#brakestamp", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 65.3);
/* the payoff: thirteenth car arrives, counter fails over to 13 */
tl.fromTo("#extra", { opacity: 0, scale: 0.6 }, { opacity: 1, scale: 1, duration: 0.4, ease: "power3.out" }, 71.6);
tl.to("#cnum", { duration: 0.85, scrambleText: { text: "13", chars: "0123456789", speed: 0.7, revealDelay: 0.3 } }, 71.5);
tl.fromTo("#cnum", { color: "#ffffff", scale: 1 }, { color: "#ff4242", scale: 1.3, duration: 0.4, ease: "power3.out" }, 71.9);
